import {weapons,starterWeaponIds,migrateWeaponId} from './catalog.js';
const defaults={sensitivity:1,fov:85,aimZoom:1.5,scopeZoom:3.5,volume:60,music:25,shake:true,shadows:true,mobileAimAssist:true,mobileAutoFire:true};
const ranges={sensitivity:[.2,2.5],fov:[65,110],aimZoom:[1,4],scopeZoom:[1,8],volume:[0,100],music:[0,100]};
export function normalizeSettings(value){const input=value&&typeof value==='object'&&!Array.isArray(value)?value:{},out={...defaults};for(const [key,[min,max]]of Object.entries(ranges))if(typeof input[key]==='number'&&Number.isFinite(input[key]))out[key]=Math.max(min,Math.min(max,input[key]));for(const key of ['shake','shadows','mobileAimAssist','mobileAutoFire'])if(typeof input[key]==='boolean')out[key]=input[key];return out}
export function normalizeLoadout(weapon,slots,legacy=false){const valid=id=>Number.isInteger(id)&&id>=0&&id<weapons.length,convert=id=>legacy&&Number.isInteger(id)?migrateWeaponId(id):id,slot=w=>w.mechanic==='melee'?2:w.cat==='hg'?1:0;weapon=convert(weapon);const list=Array.isArray(slots)?slots:starterWeaponIds;return{weapon:valid(weapon)?weapon:0,slots:starterWeaponIds.map((fallback,i)=>{const id=convert(list[i]);return valid(id)&&slot(weapons[id])===i?id:fallback})}}
export function normalizeRecords(value,mapCount=10){if(!Array.isArray(value))return[];return value.filter(r=>r&&typeof r==='object'&&Number.isInteger(r.map)&&r.map>=0&&r.map<mapCount&&Number.isFinite(r.date)&&r.date>=0&&['waves','timed','bots','training','online'].includes(r.mode)).map(r=>({...r,kills:Number.isFinite(r.kills)?Math.max(0,Math.floor(r.kills)):0,score:Number.isFinite(r.score)?Math.max(0,Math.floor(r.score)):0,wave:Number.isFinite(r.wave)?Math.max(0,Math.floor(r.wave)):0,time:Number.isFinite(r.time)?Math.max(0,Math.floor(r.time)):0})).slice(-200)}
